"use client";
import Image from"next/image";import Link from"next/link";import{usePathname}from"next/navigation";import{useState}from"react";import{AlertTriangle,ArrowRight,Bell,CalendarDays,CheckCircle2,ChevronDown,ChevronUp,ClipboardCheck,Clock,Edit3,Eye,FileQuestion,FileText,GripVertical,ImageIcon,Landmark,Mic,MicOff,MoreHorizontal,Plus,Save,Search,Trash2,Upload,Video,VideoOff,X}from"lucide-react";import{TeacherShell}from"./teacher-shell";import{assessments,curriculumModules,initialAnnouncements,initialNotifications,questionBank,teacher,teacherClasses,teacherCourses,teacherStudents}from"@/lib/mock-data/teacher-portal";
const primary="inline-flex min-h-10 items-center justify-center gap-2 rounded bg-brand px-4 text-sm font-bold text-white transition hover:bg-brand-dark disabled:opacity-50";const secondary="inline-flex min-h-10 items-center justify-center gap-2 rounded border border-[#d8b8c4] bg-white px-4 text-sm font-bold text-deep-blue transition hover:border-brand hover:text-brand";const panel="rounded-lg border border-[#e6cbd5] bg-white";const input="min-h-11 w-full rounded border border-[#d8b8c4] bg-white px-3 text-sm focus:border-brand";
function Toast({text,onClose}:{text:string;onClose:()=>void}){return <div role="status" className="fixed bottom-22 right-4 z-60 flex max-w-sm items-center gap-3 rounded-lg bg-[#173f32] px-4 py-3 text-sm font-semibold text-white shadow-xl lg:bottom-6"><CheckCircle2 size={18}/><span>{text}</span><button onClick={onClose} aria-label="Dismiss"><X size={16}/></button></div>}
function Confirm({title,body,onCancel,onConfirm,danger=false}:{title:string;body:string;onCancel:()=>void;onConfirm:()=>void;danger?:boolean}){return <div className="fixed inset-0 z-60 grid place-items-center bg-black/40 p-4"><div role="dialog" aria-modal="true" className={`${panel} w-full max-w-md p-6`}><h2 className="text-xl font-bold">{title}</h2><p className="mt-3 text-sm leading-6 text-muted">{body}</p><div className="mt-6 flex justify-end gap-3"><button className={secondary} onClick={onCancel}>Cancel</button><button className={danger?"inline-flex min-h-10 items-center rounded bg-red-700 px-4 text-sm font-bold text-white":primary} onClick={onConfirm}>Confirm</button></div></div></div>}
function PageHead({title,description,action}:{title:string;description?:string;action?:React.ReactNode}){return <header className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 className="text-2xl font-bold tracking-tight sm:text-3xl">{title}</h2>{description&&<p className="mt-2 text-sm text-muted">{description}</p>}</div>{action}</header>}
function Stat({label,value,detail}:{label:string;value:string|number;detail?:string}){return <div className="border-l-2 border-brand px-4"><p className="text-xs font-bold uppercase tracking-wider text-muted">{label}</p><strong className="mt-1 block text-2xl">{value}</strong>{detail&&<span className="text-xs text-muted">{detail}</span>}</div>}
function Status({children}:{children:string}){const cls=children==="On Track"||children==="Published"||children==="Present"?"bg-green-50 text-green-800":children==="Needs Attention"||children==="Draft"||children==="Late"?"bg-amber-50 text-amber-800":"bg-slate-100 text-slate-700";return <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-bold ${cls}`}>{children}</span>}
function Tabs({items,active,setActive}:{items:string[];active:string;setActive:(x:string)=>void}){return <div role="tablist" className="mb-5 flex gap-1 overflow-x-auto border-b border-[#e4c7d1]">{items.map(x=><button role="tab" aria-selected={active===x} key={x} onClick={()=>setActive(x)} className={`min-h-11 shrink-0 border-b-2 px-4 text-sm font-bold ${active===x?"border-brand text-brand":"border-transparent text-muted"}`}>{x}</button>)}</div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="block text-xs font-bold uppercase tracking-wide text-[#65515a]"><span className="mb-2 block">{label}</span>{children}</label>}
function Empty({title,body,href,label}:{title:string;body:string;href?:string;label?:string}){return <div className={`${panel} grid min-h-56 place-items-center p-8 text-center`}><div><FileQuestion className="mx-auto text-brand"/><h3 className="mt-4 font-bold">{title}</h3><p className="mt-2 text-sm text-muted">{body}</p>{href&&<Link href={href} className={`${primary} mt-5`}>{label}</Link>}</div></div>}
function Dashboard(){return <><PageHead title="Good morning, Dr. Sarah" description="You have 2 classes and 3 items needing attention today."/><div className="grid gap-5 xl:grid-cols-[1.4fr_.6fr]"><div className="space-y-5"><section className="rounded-lg bg-gradient-to-r from-[#830053] to-[#a4226c] p-6 text-white"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-center"><div><div className="flex items-center gap-3 text-xs font-bold"><span className="rounded bg-white px-2 py-1 text-brand">NEXT CLASS</span><Clock size={15}/>Starts in 2h 18m</div><h3 className="mt-4 text-2xl font-bold">Clinical Enzyme Interpretation</h3><p className="mt-1 text-pink-100">Clinical Biochemistry • CB-2026-A • 186 students</p><p className="mt-3 text-sm">Resources Ready ✓ &nbsp; • &nbsp; 2 Student Questions</p></div><div className="flex gap-2"><Link href="/teacher/live-classes" className="rounded border border-white/50 px-4 py-3 text-sm font-bold">View Details</Link><Link href="/teacher/live-classes/clinical-enzyme-interpretation" className="rounded bg-white px-4 py-3 text-sm font-bold text-brand">Open Class</Link></div></div></section><div className="grid gap-5 md:grid-cols-2"><section className={`${panel} p-5`}><h3 className="flex items-center gap-2 text-lg font-bold"><AlertTriangle className="text-amber-600"/>Needs Attention</h3><div className="mt-4 divide-y divide-[#f0dde4]">{[["12 assessment submissions require review","Review"],["8 students below 50% progress","View Students"],["Module 04 is still Draft","Complete Module"]].map(x=><div key={x[0]} className="flex items-center justify-between gap-3 py-3 text-sm"><span>{x[0]}</span><button className="font-bold text-brand">{x[1]}</button></div>)}</div></section><section className={`${panel} p-5`}><h3 className="text-lg font-bold">Student Progress</h3><div className="mt-6 grid grid-cols-[110px_1fr] items-center gap-5"><div className="grid aspect-square place-items-center rounded-full border-[12px] border-green-700 border-r-amber-500 border-b-slate-200"><strong className="text-xl">68%</strong></div><div className="space-y-3 text-sm"><p><b className="text-green-800">142</b> On Track</p><p><b className="text-amber-700">31</b> Needs Attention</p><p><b className="text-slate-600">13</b> Inactive</p></div></div><Link href="/teacher/students" className="mt-5 block text-sm font-bold text-brand">View Student Progress →</Link></section></div><section className={`${panel} p-5`}><div className="flex justify-between"><h3 className="text-lg font-bold">My Courses</h3><Link href="/teacher/courses" className="text-sm font-bold text-brand">Manage all</Link></div><div className="mt-4 grid gap-4 md:grid-cols-3">{teacherCourses.map(c=><CourseTile key={c.id} course={c}/>)}</div></section></div><aside className={`${panel} p-5`}><h3 className="text-lg font-bold">Today</h3><div className="mt-5 border-l-2 border-[#eadbe1] pl-5">{[["10:00 AM","Hematology Case Discussion"],["3:30 PM","Microbiology Revision"],["7:30 PM","Clinical Biochemistry Live Session"],["Tomorrow","Student Q&A"]].map((x,i)=><div key={x[0]} className="relative pb-7"><span className={`absolute -left-[27px] top-1 h-3 w-3 rounded-full ${i===2?"bg-brand ring-4 ring-brand/15":"bg-slate-300"}`}/><p className="text-xs font-bold text-muted">{x[0]}</p><p className="mt-1 text-sm font-semibold">{x[1]}</p></div>)}</div><div className="border-t border-[#eadbe1] pt-5"><h3 className="font-bold">Teacher Snapshot</h3><div className="mt-4 grid grid-cols-2 gap-y-5"><Stat label="Courses" value="3"/><Stat label="Students" value="284"/><Stat label="Classes" value="6" detail="this week"/><Stat label="Pending" value="12"/></div></div></aside></div></>}
function CourseTile({course}:{course:(typeof teacherCourses)[number]}){return <article className="overflow-hidden rounded border border-[#ead1da]"><div className="relative h-24"><Image src={course.image} alt="" fill className="object-cover" sizes="320px"/></div><div className="p-4"><Status>{course.status}</Status><h3 className="mt-3 font-bold">{course.title}</h3><p className="mt-1 text-xs text-muted">{course.students} students • {course.modules} modules</p><div className="mt-3 h-1.5 rounded bg-slate-100"><div className="h-full rounded bg-brand" style={{width:`${course.progress}%`}}/></div><div className="mt-4 flex gap-3 text-xs font-bold"><Link href={`/teacher/courses/${course.id}`} className="text-brand">Manage Course</Link><Link href="/teacher/students" className="text-deep-blue">View Students</Link></div></div></article>}
function Courses(){const[tab,setTab]=useState("Active");const[q,setQ]=useState("");const list=teacherCourses.filter(c=>(tab==="Active"?c.status==="Published":c.status===tab)&&c.title.toLowerCase().includes(q.toLowerCase()));return <><PageHead title="My Courses" description="Manage your assigned courses, learning content and students."/><Tabs items={["Active","Draft","Archived"]} active={tab} setActive={setTab}/><label className="relative mb-5 block max-w-md"><Search className="absolute left-3 top-3 text-muted" size={17}/><span className="sr-only">Search my courses</span><input className={`${input} pl-10`} value={q} onChange={e=>setQ(e.target.value)} placeholder="Search my courses..."/></label>{list.length?<div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{list.map(c=><CourseTile key={c.id} course={c}/>)}</div>:<Empty title="No assigned courses" body="There are no courses in this view."/>}</>}
function CourseManagement(){const[tab,setTab]=useState("Curriculum");return <><PageHead title="Clinical Biochemistry" description="Dr. Sarah Ahmed • Published • 186 students" action={<div className="flex gap-2"><Link href="/student/courses/clinical-biochemistry" className={secondary}><Eye size={16}/>Preview as Student</Link><Link href="/teacher/courses/clinical-biochemistry/curriculum" className={primary}>Manage Curriculum</Link></div>}/><div className={`${panel} mb-6 grid gap-4 p-5 sm:grid-cols-4`}><Stat label="Modules" value="12"/><Stat label="Lessons" value="31"/><Stat label="Students" value="186"/><Stat label="Average Progress" value="72%"/></div><Tabs items={["Curriculum","Students","Assessments","Resources","Settings"]} active={tab} setActive={setTab}/>{tab==="Curriculum"&&<div className="space-y-3">{curriculumModules.map((m,i)=><div className={`${panel} flex items-center justify-between p-4`} key={m.title}><div><span className="text-xs font-bold text-brand">MODULE {String(i+1).padStart(2,"0")}</span><h3 className="mt-1 font-bold">{m.title}</h3><p className="text-xs text-muted">{m.lessons.length} lessons</p></div><Status>{m.status}</Status></div>)}</div>}{tab==="Students"&&<Students compact/>}{tab==="Assessments"&&<AssessmentCards/>}{tab==="Resources"&&<ResourceRows/>}{tab==="Settings"&&<SettingsPage course/>}</>}
function Curriculum(){const[mods,setMods]=useState(curriculumModules);const[open,setOpen]=useState(2);const[confirm,setConfirm]=useState<number|null>(null);const[toast,setToast]=useState("");function move(i:number,d:number){const n=i+d;if(n<0||n>=mods.length)return;const copy=[...mods];[copy[i],copy[n]]=[copy[n],copy[i]];setMods(copy);setToast("Module order updated")};return <><PageHead title="Curriculum Builder" description="Clinical Biochemistry • Draft saved" action={<button className={primary} onClick={()=>setToast("Curriculum published")}>Publish Changes</button>}/><div className="mb-5 flex gap-2"><Link href="/teacher/courses/clinical-biochemistry/lessons/new" className={primary}><Plus size={17}/>Add Lesson</Link><button className={secondary} onClick={()=>{setMods([...mods,{title:"Untitled Module",status:"Draft",lessons:[]}]);setToast("Module added")}}><Plus size={17}/>Add Module</button></div><div className="space-y-3">{mods.map((m,i)=><section key={`${m.title}-${i}`} className={`${panel} overflow-hidden`}><div className="flex items-center gap-2 p-4"><GripVertical className="text-slate-400" size={18}/><button className="grid h-10 w-10 place-items-center" onClick={()=>setOpen(open===i?-1:i)} aria-label={`${open===i?"Collapse":"Expand"} ${m.title}`}>{open===i?<ChevronUp/>:<ChevronDown/>}</button><div className="min-w-0 flex-1"><p className="text-xs font-bold text-brand">MODULE {String(i+1).padStart(2,"0")}</p><h3 className="truncate font-bold">{m.title}</h3></div><Status>{m.status}</Status><button aria-label="Move module up" onClick={()=>move(i,-1)} className="hidden h-10 w-10 place-items-center sm:grid"><ChevronUp size={17}/></button><button aria-label="Move module down" onClick={()=>move(i,1)} className="hidden h-10 w-10 place-items-center sm:grid"><ChevronDown size={17}/></button><button aria-label="Delete module" onClick={()=>setConfirm(i)} className="grid h-10 w-10 place-items-center text-red-700"><Trash2 size={17}/></button></div>{open===i&&<div className="border-t border-[#ead1da] bg-[#faf8ff] p-3 sm:p-5"><div className="space-y-2">{m.lessons.map((l,j)=><div key={l} className="flex items-center gap-3 rounded border border-[#ead1da] bg-white p-3"><span className="grid h-8 w-8 shrink-0 place-items-center bg-brand/10 text-brand">{j===m.lessons.length-1?<ClipboardCheck size={15}/>:j%2?<FileText size={15}/>:<Video size={15}/>}</span><span className="min-w-0 flex-1 truncate text-sm font-semibold">{l}</span><Link href={`/teacher/courses/clinical-biochemistry/lessons/${j===3?"diagnostic-enzyme-markers":"new"}/edit`} className="text-xs font-bold text-brand">Edit</Link><Link href="/student/learn/diagnostic-enzyme-markers" className="text-xs font-bold text-deep-blue">Preview</Link><button aria-label={`More actions for ${l}`}><MoreHorizontal/></button></div>)}</div><Link href="/teacher/courses/clinical-biochemistry/lessons/new" className={`${secondary} mt-3`}><Plus size={16}/>Add content</Link></div>}</section>)}</div>{confirm!==null&&<Confirm title="Delete module?" body="This removes the module from the current frontend session. Published course data is not connected yet." danger onCancel={()=>setConfirm(null)} onConfirm={()=>{setMods(mods.filter((_,i)=>i!==confirm));setConfirm(null);setToast("Module deleted")}}/>}{toast&&<Toast text={toast} onClose={()=>setToast("")}/>}</>}
function LessonEditor({reading=false}:{reading?:boolean}){const[dirty,setDirty]=useState(false);const[upload,setUpload]=useState(0);const[resources,setResources]=useState(["Clinical Enzyme Reference Sheet.pdf","Reference Values.pdf"]);const[blocks,setBlocks]=useState(["Heading","Paragraph","Key Concept","Clinical Note"]);const[toast,setToast]=useState("");function simulate(){setUpload(35);setTimeout(()=>setUpload(72),350);setTimeout(()=>setUpload(100),750)}return <><PageHead title={reading?"Reading Lesson Editor":"Add / Edit Video Lesson"} description="Clinical Biochemistry • Module 03"/><form className={`${panel} space-y-6 p-5 sm:p-7`} onChange={()=>setDirty(true)} onSubmit={e=>{e.preventDefault();setDirty(false);setToast("Lesson saved")}}><div className="grid gap-5 md:grid-cols-2"><Field label="Lesson Title"><input className={input} defaultValue={reading?"Laboratory Reference Ranges":"Diagnostic Enzyme Markers"}/></Field><Field label="Module"><select className={input} defaultValue="Module 03"><option>Module 03</option><option>Module 04</option></select></Field></div><Field label="Short Description"><textarea className={`${input} min-h-24 py-3`} defaultValue="Interpret common diagnostic enzyme markers in clinical context."/></Field>{reading?<><div><h3 className="font-bold">Content Blocks</h3><div className="mt-3 space-y-2">{blocks.map((b,i)=><div key={`${b}-${i}`} className="flex items-center gap-3 rounded border border-[#ead1da] p-3"><GripVertical size={16}/><span className="flex-1 text-sm font-semibold">{b}</span><button type="button" onClick={()=>i&&setBlocks(blocks.map((x,j)=>j===i?blocks[i-1]:j===i-1?b:x))} aria-label="Move block up"><ChevronUp/></button><button type="button" onClick={()=>setBlocks(blocks.filter((_,j)=>j!==i))} aria-label="Remove block"><Trash2/></button></div>)}</div><button type="button" className={`${secondary} mt-3`} onClick={()=>setBlocks([...blocks,"Exam Tip"])}><Plus/>Add block</button></div></>:<><Field label="Video"><div className="rounded border border-dashed border-[#cfa5b5] bg-[#faf8ff] p-6 text-center"><Upload className="mx-auto text-brand"/><button type="button" onClick={simulate} className={`${secondary} mt-3`}>Choose Video</button>{upload>0&&<div className="mx-auto mt-4 max-w-sm"><div className="h-2 rounded bg-slate-200"><div className="h-full rounded bg-brand transition-all" style={{width:`${upload}%`}}/></div><p className="mt-2 text-xs font-bold">{upload<100?`Uploading ${upload}%`:"Ready ✓"}</p></div>}</div></Field><div className="grid gap-5 md:grid-cols-2"><Field label="Duration"><input className={input} defaultValue="22 min"/></Field><Field label="Video URL"><input className={input} placeholder="https://..."/></Field></div></>}<Field label="Lesson Overview"><textarea className={`${input} min-h-32 py-3`} defaultValue="This lesson explains how enzyme patterns support clinical diagnosis."/></Field><div><h3 className="font-bold">Resources</h3><div className="mt-3 space-y-2">{resources.map(r=><div key={r} className="flex items-center justify-between rounded border border-[#ead1da] p-3 text-sm"><span>{r}</span><button type="button" onClick={()=>setResources(resources.filter(x=>x!==r))} className="text-red-700">Remove</button></div>)}</div><button type="button" className={`${secondary} mt-3`} onClick={()=>setResources([...resources,"New Resource.pdf"])}>Add Resource</button></div><Field label="Status"><select className={input}><option>Draft</option><option>Published</option></select></Field><div className="flex flex-wrap justify-end gap-3"><Link href="/student/learn/diagnostic-enzyme-markers" className={secondary}>Preview</Link><button type="button" className={secondary} onClick={()=>{setDirty(false);setToast("Draft saved")}}>Save as Draft</button><button className={primary}><Save size={16}/>Save Lesson</button></div>{dirty&&<p className="text-xs font-semibold text-amber-700">You have unsaved changes.</p>}</form>{toast&&<Toast text={toast} onClose={()=>setToast("")}/>}</>}
function Students({compact=false}:{compact?:boolean}){const[q,setQ]=useState("");const[status,setStatus]=useState("All");const[course,setCourse]=useState("All");const list=teacherStudents.filter(s=>(status==="All"||s.status===status)&&(course==="All"||s.course===course)&&s.name.toLowerCase().includes(q.toLowerCase()));return <div>{!compact&&<PageHead title="Students" description="Track enrolled students and identify who may need support."/>}<div className="mb-5 grid gap-3 sm:grid-cols-3"><label className="relative sm:col-span-1"><Search className="absolute left-3 top-3 text-muted" size={17}/><span className="sr-only">Search students</span><input className={`${input} pl-10`} value={q} onChange={e=>setQ(e.target.value)} placeholder="Search students..."/></label><select aria-label="Filter by course" className={input} value={course} onChange={e=>setCourse(e.target.value)}><option>All</option>{teacherCourses.map(c=><option key={c.id}>{c.title}</option>)}</select><select aria-label="Filter by progress status" className={input} value={status} onChange={e=>setStatus(e.target.value)}><option>All</option><option>On Track</option><option>Needs Attention</option><option>Inactive</option></select></div>{list.length?<><div className={`${panel} hidden overflow-hidden md:block`}><table className="w-full text-left text-sm"><thead className="bg-deep-blue text-white"><tr>{["Student","Course","Progress","Last Active","Quiz Average","Status","Action"].map(x=><th className="px-4 py-3" key={x}>{x}</th>)}</tr></thead><tbody>{list.map(s=><tr key={s.id} className="border-t border-[#ead1da]"><td className="px-4 py-3 font-bold">{s.name}</td><td className="px-4 py-3">{s.course}</td><td className="px-4 py-3">{s.progress}%</td><td className="px-4 py-3">{s.lastActive}</td><td className="px-4 py-3">{s.quizAverage}%</td><td className="px-4 py-3"><Status>{s.status}</Status></td><td className="px-4 py-3"><Link href={`/teacher/students/${s.id}`} className="font-bold text-brand">View</Link></td></tr>)}</tbody></table></div><div className="grid gap-3 md:hidden">{list.map(s=><Link key={s.id} href={`/teacher/students/${s.id}`} className={`${panel} p-4`}><div className="flex justify-between gap-3"><h3 className="font-bold">{s.name}</h3><Status>{s.status}</Status></div><p className="mt-1 text-xs text-muted">{s.course}</p><div className="mt-4 grid grid-cols-3 gap-2 text-xs"><span><b className="block text-base">{s.progress}%</b>Progress</span><span><b className="block text-base">{s.quizAverage}%</b>Quiz Avg</span><span><b className="block text-base">{s.lastActive}</b>Active</span></div></Link>)}</div></>:<Empty title="No students" body="No students match the current filters."/>}</div>}
function StudentDetail(){const[modal,setModal]=useState(false);const[toast,setToast]=useState("");const s=teacherStudents[0];return <><PageHead title={s.name} description={`${s.course} • ${s.status}`} action={<button className={primary} onClick={()=>setModal(true)}>Recommend Lesson</button>}/><div className={`${panel} grid gap-5 p-5 sm:grid-cols-5`}><Stat label="Progress" value={`${s.progress}%`}/><Stat label="Lessons" value="22 / 31"/><Stat label="Quiz Average" value={`${s.quizAverage}%`}/><Stat label="Last Active" value={s.lastActive}/><Stat label="Study Time" value={s.studyTime}/></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><section className={`${panel} p-5`}><h3 className="text-lg font-bold">Module Progress</h3>{[["Module 01",100],["Module 02",100],["Module 03",75],["Module 04",20]].map(x=><div key={x[0]} className="mt-4"><div className="flex justify-between text-sm"><span>{x[0]}</span><b>{x[1]}%</b></div><div className="mt-2 h-2 rounded bg-slate-100"><div className="h-full rounded bg-brand" style={{width:`${x[1]}%`}}/></div></div>)}</section><section className={`${panel} p-5`}><h3 className="text-lg font-bold">Assessment Performance</h3>{[["Clinical Biochemistry Quiz","90%"],["Module 02 Assessment","82%"],["Module 03 Assessment","74%"]].map(x=><div className="flex justify-between border-b border-[#ead1da] py-3 text-sm" key={x[0]}><span>{x[0]}</span><b>{x[1]}</b></div>)}<p className="mt-4 text-sm"><b>Weak areas:</b> Clinical Interpretation, Carbohydrate Metabolism</p><div className="mt-5 flex flex-wrap gap-2"><button className={secondary} onClick={()=>setToast("Message composer opened")}>Send Message</button><button className={secondary} onClick={()=>setToast("Exam attempts opened")}>View Exam Attempts</button></div></section></div>{modal&&<div className="fixed inset-0 z-60 grid place-items-center bg-black/40 p-4"><div className={`${panel} w-full max-w-md p-6`}><h2 className="text-xl font-bold">Recommend Lesson</h2><select className={`${input} mt-5`}><option>Diagnostic Enzyme Markers</option><option>Liver Function Tests</option></select><div className="mt-5 flex justify-end gap-2"><button className={secondary} onClick={()=>setModal(false)}>Cancel</button><button className={primary} onClick={()=>{setModal(false);setToast("Lesson recommended to Ameen")}}>Recommend</button></div></div></div>}{toast&&<Toast text={toast} onClose={()=>setToast("")}/>}</>}
function LiveClasses(){const[tab,setTab]=useState("Upcoming");const list=teacherClasses.filter(c=>c.status===tab);return <><PageHead title="Live Classes" description="Schedule, prepare and deliver focused learning sessions." action={<Link href="/teacher/live-classes/new" className={primary}><Plus/>Schedule Class</Link>}/><Tabs items={["Upcoming","Past","Draft"]} active={tab} setActive={setTab}/><div className="grid gap-4 lg:grid-cols-2">{list.map(c=><article key={c.id} className={`${panel} p-5`}><div className="flex justify-between"><Status>{c.status}</Status><CalendarDays className="text-brand"/></div><p className="mt-4 text-xs font-bold text-brand">{c.course}</p><h3 className="mt-1 text-xl font-bold">{c.title}</h3><p className="mt-2 text-sm text-muted">{c.date} • {c.batch} • {c.students} students</p>{c.status==="Past"&&<p className="mt-2 text-sm">Attendance: {c.attendance} • Duration: {c.duration}</p>}<div className="mt-5 flex flex-wrap gap-2">{c.status==="Upcoming"&&<Link className={primary} href={`/teacher/live-classes/${c.id}`}>Start Class</Link>}<button className={secondary}>{c.status==="Past"?"View Session":"Edit"}</button><button className={secondary}>View Questions</button></div></article>)}</div>{!list.length&&<Empty title={`No ${tab.toLowerCase()} classes`} body="Classes in this status will appear here." href="/teacher/live-classes/new" label="Schedule Class"/>}</>}
