function Notifications(){const[items,setItems]=useState(initialNotifications);const[tab,setTab]=useState("All");const list=items.filter(n=>tab==="All"||!n.read);return <><PageHead title="Notifications" description="Class, assessment and student activity updates." action={<button className={secondary} onClick={()=>setItems(items.map(x=>({...x,read:true})))}>Mark All Read</button>}/><Tabs items={["All","Unread"]} active={tab} setActive={setTab}/>{list.length?<div className="space-y-2">{list.map(n=><article className={`${panel} flex items-center gap-4 p-4 ${n.read?"opacity-70":"border-l-4 border-l-brand"}`} key={n.id}><span className="grid h-10 w-10 place-items-center bg-brand/10 text-brand"><Bell size={18}/></span><div className="flex-1"><p className="text-xs font-bold text-brand">{n.kind}</p><p className="text-sm font-semibold">{n.message}</p><p className="text-xs text-muted">{n.time}</p></div>{!n.read&&<button className="text-xs font-bold text-brand" onClick={()=>setItems(items.map(x=>x.id===n.id?{...x,read:true}:x))}>Mark Read</button>}</article>)}</div>:<Empty title="No notifications" body="You're all caught up."/>}</>}
function Profile(){const[edit,setEdit]=useState(false);const[toast,setToast]=useState("");return <><PageHead title="Teacher Profile" description="Manage your public faculty information." action={<button className={edit?primary:secondary} onClick={()=>{if(edit)setToast("Profile saved");setEdit(!edit)}}>{edit?<><Save/>Save</>:<><Edit3/>Edit Profile</>}</button>}/><div className="grid gap-5 lg:grid-cols-[320px_1fr]"><aside className={`${panel} p-6 text-center`}><div className="mx-auto grid h-24 w-24 place-items-center rounded-full bg-deep-blue text-2xl font-bold text-white">SA</div><h3 className="mt-4 text-xl font-bold">{teacher.name}</h3><p className="text-sm text-muted">{teacher.role}</p><div className="mt-6 grid grid-cols-3 gap-2"><Stat label="Courses" value="3"/><Stat label="Students" value="284"/><Stat label="Classes" value="42"/></div></aside><section className={`${panel} grid gap-5 p-6 md:grid-cols-2`}>{[["Full Name",teacher.name],["Email",teacher.email],["Mobile",teacher.mobile],["Specialization",teacher.specialization],["Qualification",teacher.qualification],["Years of Experience",teacher.experience]].map(x=><Field key={x[0]} label={x[0]}><input className={input} defaultValue={x[1]} disabled={!edit}/></Field>)}<div className="md:col-span-2"><Field label="Bio"><textarea className={`${input} min-h-28 py-3`} defaultValue={teacher.bio} disabled={!edit}/></Field></div></section></div>{toast&&<Toast text={toast} onClose={()=>setToast("")}/>}</>}
function SettingsPage({course=false}:{course?:boolean}){const[toast,setToast]=useState("");return <><PageHead title={course?"Course Settings":"Teacher Settings"} description={course?"Manage course visibility and teaching defaults.":"Account, notifications, teaching preferences and security."}/><div className="grid gap-5 lg:grid-cols-[220px_1fr]"><nav className={`${panel} h-fit p-2`}>{["Account","Notifications","Teaching Preferences","Security"].map(x=><button key={x} className="block min-h-11 w-full rounded px-3 text-left text-sm font-bold hover:bg-brand/10">{x}</button>)}</nav><div className="space-y-5"><section className={`${panel} p-5`}><h3 className="font-bold">Notification Preferences</h3><div className="mt-4 space-y-4">{["Upcoming Classes","Student Questions","Assessment Activity","Students Needing Attention","Announcements"].map(x=><label className="flex items-center justify-between text-sm" key={x}>{x}<input type="checkbox" defaultChecked className="h-5 w-5"/></label>)}</div></section><section className={`${panel} grid gap-5 p-5 md:grid-cols-2`}><Field label="Default Class Duration"><select className={input}><option>60 minutes</option></select></Field><Field label="Result Visibility"><select className={input}><option>After Assessment Ends</option></select></Field><Field label="Default Reminder"><select className={input}><option>1 Hour Before</option></select></Field></section><section className={`${panel} p-5`}><h3 className="font-bold">Security</h3><p className="mt-2 text-sm text-muted">Password and active session controls are demonstration-only.</p><button className={`${secondary} mt-4`} onClick={()=>setToast("Password change demo opened")}>Change Password</button></section><div className="flex justify-end"><button className={primary} onClick={()=>setToast("Settings saved")}>Save Settings</button></div></div></div>{toast&&<Toast text={toast} onClose={()=>setToast("")}/>}</>}
function Help(){const[q,setQ]=useState("");const[open,setOpen]=useState(0);const[done,setDone]=useState(false);const faqs=["How do I publish a lesson?","How do I schedule a live class?","How do I review student progress?","How do I create an assessment?","How do I add questions to the question bank?"];return <><PageHead title="Help & Support" description="Find answers and get teacher-specific support."/><label className="relative block"><Search className="absolute left-4 top-4"/><span className="sr-only">Search help</span><input className={`${input} min-h-14 pl-12`} value={q} onChange={e=>setQ(e.target.value)} placeholder="Search help..."/></label><div className="mt-5 grid gap-3 sm:grid-cols-3">{["Courses & Content","Students","Live Classes","Assessments","Question Bank","Account"].map(x=><div className={`${panel} p-4 font-bold`} key={x}>{x}</div>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-[1fr_360px]"><section className={panel}>{faqs.filter(x=>x.toLowerCase().includes(q.toLowerCase())).map((x,i)=><div className="border-b border-[#ead1da]" key={x}><button className="flex min-h-14 w-full items-center justify-between p-4 text-left font-bold" onClick={()=>setOpen(open===i?-1:i)}>{x}<ChevronDown/></button>{open===i&&<p className="px-4 pb-4 text-sm leading-6 text-muted">Open the relevant Teacher workspace, complete the required fields, then use the primary publish or save action. A confirmation appears before important changes.</p>}</div>)}</section><form className={`${panel} space-y-4 p-5`} onSubmit={e=>{e.preventDefault();setDone(true)}}><h3 className="font-bold">Contact Support</h3>{done?<div className="rounded bg-green-50 p-4 text-sm text-green-800"><b>Request submitted</b><br/>Reference: ALS-TCH-SUP-1042</div>:<><Field label="Subject"><input className={input} required/></Field><Field label="Message"><textarea className={`${input} min-h-28 py-3`} required/></Field><button className={primary}>Submit Request</button></>}</form></div></>}
function ResourceRows(){return <div className="space-y-2">{["Clinical Biochemistry Notes.pdf","Reference Values.pdf","Enzyme Classification Chart.pdf"].map(r=><div key={r} className="flex items-center gap-3 rounded border border-[#ead1da] p-3 text-sm"><FileText className="text-brand"/><span className="flex-1">{r}</span><button className="font-bold text-brand">View</button></div>)}</div>}
function LoadingState(){return <div className="space-y-4" aria-label="Loading teacher content"><div className="skeleton h-10 w-64 rounded"/><div className="grid gap-4 md:grid-cols-3">{[1,2,3].map(x=><div key={x} className="skeleton h-40 rounded-lg"/>)}</div><div className="skeleton h-80 rounded-lg"/></div>}
function ErrorState(){return <div className={`${panel} mx-auto max-w-lg p-8 text-center`}><AlertTriangle className="mx-auto text-amber-600"/><h2 className="mt-4 text-xl font-bold">We couldn&apos;t load this teacher workspace.</h2><p className="mt-2 text-sm text-muted">Your work is unchanged. Please try again.</p><button className={`${primary} mt-5`}>Try Again</button></div>}
export function TeacherPortal(){const path=usePathname();const query=typeof window!=="undefined"?new URLSearchParams(window.location.search):null;if(query?.get("state")==="loading")return <TeacherShell title="Faculty Management"><LoadingState/></TeacherShell>;if(query?.get("state")==="error")return <TeacherShell title="Faculty Management"><ErrorState/></TeacherShell>;let page:React.ReactNode=<Dashboard/>;const title="Faculty Management";if(path==="/teacher/courses")page=<Courses/>;else if(path==="/teacher/courses/clinical-biochemistry")page=<CourseManagement/>;else if(path.endsWith("/curriculum"))page=<Curriculum/>;else if(path.includes("/lessons/")&&(path.includes("reading")||path.includes("laboratory-reference-ranges")))page=<LessonEditor reading/>;else if(path.includes("/lessons/"))page=<LessonEditor/>;else if(path==="/teacher/students")page=<Students/>;else if(path.startsWith("/teacher/students/"))page=<StudentDetail/>;else if(path==="/teacher/live-classes")page=<LiveClasses/>;else if(path==="/teacher/live-classes/new")page=<ScheduleClass/>;else if(path.endsWith("/attendance"))page=<Attendance/>;else if(path.startsWith("/teacher/live-classes/"))return <Classroom/>;else if(path==="/teacher/assessments")page=<Assessments/>;else if(path==="/teacher/assessments/new")page=<AssessmentBuilder/>;else if(path.endsWith("/results"))page=<Results/>;else if(path.endsWith("/questions"))page=<QuestionBuilder/>;else if(path.startsWith("/teacher/assessments/"))page=<AssessmentBuilder/>;else if(path==="/teacher/question-bank")page=<QuestionBank/>;else if(path==="/teacher/announcements")page=<Announcements/>;else if(path==="/teacher/notifications")page=<Notifications/>;else if(path==="/teacher/profile")page=<Profile/>;else if(path==="/teacher/settings")page=<SettingsPage/>;else if(path==="/teacher/help")page=<Help/>;return <TeacherShell title={title}>{page}</TeacherShell>}
